vector<vector<int>> res;
vector<int> cur;
void go(vector<int>& a, int i) {
    res.push_back(cur);                  // write down this pizza
    for (int j = i; j < (int)a.size(); j++) {
        cur.push_back(a[j]);             // choose
        go(a, j + 1);                    // explore later toppings only
        cur.pop_back();                  // undo
    }
}

void perm(vector<int>& a, vector<int>& cur, vector<bool>& used,
          vector<vector<int>>& res) {
    if (cur.size() == a.size()) { res.push_back(cur); return; }
    for (int i = 0; i < (int)a.size(); i++) {
        if (used[i]) continue;           // prune: already in the path
        used[i] = true; cur.push_back(a[i]);
        perm(a, cur, used, res);
        cur.pop_back(); used[i] = false;
    }
}

// a is sorted; numbers may be reused
void comb(vector<int>& a, int i, int left, vector<int>& cur,
          vector<vector<int>>& out) {
    if (left == 0) { out.push_back(cur); return; }
    for (int j = i; j < (int)a.size(); j++) {
        if (a[j] > left) break;          // prune: sorted, so stop
        cur.push_back(a[j]);
        comb(a, j, left - a[j], cur, out);
        cur.pop_back();
    }
}
